func (this *Test_org_eclipse_swt_browser_Browser) Test_setUrl_post_connection_closes_prematurely() {
	junit.AssumeTrue(SwtTestUtilIsLinux, "Handling POST in Linux is handled by SWT, so we need extra testing for the SWT code.\nThis test can be adapted to win32/cocoa, but that would be testing the third-party\nbrowser component. Therefore (for now) this test only runs on Linux.\n")
	{
		anon155 := &Test_org_eclipse_swt_browser_BrowserAnon11{}
		anon155.impl = anon155
		anon155.initEchoHttpServer()
		anon155.fnhandlePostEcho_ = func(exchange *jrt.HttpExchange) {
			exchange.Close()
		}
		var server *EchoHttpServer = &anon155.EchoHttpServer
		defer server.Close()
		var url string = server.PostEchoUrl()
		var postData string = "test_setUrl_remote_with_post"
		var browserSetFunc jrt.Runnable = jrt.NewRunnable(func() {
			this.testLog.Append(fmt.Sprintf("Setting Browser url to:%s", url))
			var opSuccess bool = this.browser.SetUrlUrlPostDataHeaders(url, postData, nil)
			junit.AssertTrue(opSuccess)
		})
		var completed *jrt.AtomicReference = jrt.NewAtomicReference(false)
		this.browser.AddProgressListener(browser.ProgressListenerCompletedAdapter(func(event *browser.ProgressEvent) {
			this.testLog.Append("ProgressListener fired")
			completed.Set(true)
		}))
		browserSetFunc.Run()
		this.shell.Open()
		var hasFinished bool = this.WaitForPassCondition(func() bool {
			return jrt.Cast[bool](completed.Get())
		})
		junit.AssertTrue(hasFinished)
		var lowerCase string = jrt.ToLowerCase(this.browser.GetText())
		junit.AssertTrue(strings.Contains(lowerCase, jrt.ToLowerCase("Unexpected end of file from server")), fmt.Sprintf("Browser getText was: %s", this.browser.GetText()))
	}
}

